package com.today.app.ui.components

import android.content.Context
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.vector.PathParser
import androidx.core.graphics.toColorInt
import org.json.JSONObject

/**
 * The illustrated character's art, generated by the authoring tool into assets/character_art.json:
 * part key ("eyes.SLIM.almond.happy") -> layers, drawn in a 200 x 545 box whose top is y = -45.
 */
object CharacterArt {
    const val W = 200f
    const val H = 545f
    const val TOP = -45f

    @Volatile
    private var parts: Map<String, List<ArtLayer>>? = null

    internal fun parts(context: Context): Map<String, List<ArtLayer>> =
        parts ?: synchronized(this) { parts ?: load(context).also { parts = it } }

    /** Parses everything once, e.g. from a background thread at app start. */
    fun preload(context: Context) {
        parts(context)
    }

    private fun load(context: Context): Map<String, List<ArtLayer>> {
        val text = context.assets.open("character_art.json").use { it.readBytes().decodeToString() }
        val root = JSONObject(text).getJSONObject("parts")
        val pathCache = HashMap<String, Path>()
        fun pathOf(d: String) = pathCache.getOrPut(d) { PathParser().parsePathString(d).toPath() }
        val out = HashMap<String, List<ArtLayer>>()
        for (key in root.keys()) {
            val arr = root.getJSONArray(key)
            out[key] = List(arr.length()) { i ->
                val l = arr.getJSONArray(i)
                ArtLayer(
                    path = pathOf(l.getString(0)),
                    fill = Paint.parse(l.getString(1)),
                    stroke = Paint.parse(l.getString(2)),
                    width = l.getDouble(3).toFloat(),
                    alpha = l.getDouble(4).toFloat(),
                    clip = l.getString(5).takeIf { it.isNotEmpty() }?.let(::pathOf),
                )
            }
        }
        return out
    }
}

internal class ArtLayer(val path: Path, val fill: Paint?, val stroke: Paint?, val width: Float, val alpha: Float, val clip: Path?)

/** A fill / stroke: a palette role ("skin"), a fixed colour, or a gradient between two of them. */
internal sealed interface Paint {
    data class Role(val name: String) : Paint
    data class Fixed(val color: Color) : Paint
    data class Linear(val a: Paint, val b: Paint, val start: Offset, val end: Offset) : Paint
    data class Radial(val base: Paint, val alpha: Float, val center: Offset, val radius: Float) : Paint

    companion object {
        fun parse(spec: String): Paint? {
            if (spec.isEmpty()) return null
            val p = spec.split(":")
            return when (p[0]) {
                "lin" -> Linear(single(p[1]), single(p[2]), Offset(p[3].toFloat(), p[4].toFloat()), Offset(p[5].toFloat(), p[6].toFloat()))
                "rad" -> Radial(single(p[1]), p[2].toFloat(), Offset(p[3].toFloat(), p[4].toFloat()), p[5].toFloat())
                else -> single(spec)
            }
        }

        private fun single(s: String): Paint =
            if (s.startsWith("#")) Fixed(Color(s.toColorInt())) else Role(s)
    }
}
